using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.Linq;
using System.Net.Sockets;
using System.Security.Cryptography;
using System.Text;
using System.Threading;
using System.Web.Script.Serialization;
namespace BF4Bots {
public sealed class RotationEntry {
 public string Map{get;set;} public string Mode{get;set;} public int Rounds{get;set;}
 public string Signature{get{return Map+"|"+Mode+"|"+Rounds;}}
}
public sealed class Rcon : IDisposable {
 TcpClient client;NetworkStream stream;uint sequence;string lastHost,lastPassword;int lastPort;readonly object gate=new object();
 public bool Connected{get{return client!=null&&client.Connected;}}
 public static byte[] Encode(uint sequence,string[] words){using(var body=new MemoryStream())using(var w=new BinaryWriter(body)){foreach(string word in words){var bytes=Encoding.UTF8.GetBytes(word);if(bytes.Length>65536||word.IndexOf('\0')>=0)throw new InvalidDataException("Palavra RCON inválida.");w.Write((uint)bytes.Length);w.Write(bytes);w.Write((byte)0);}using(var packet=new MemoryStream())using(var h=new BinaryWriter(packet)){h.Write(sequence);h.Write((uint)(12+body.Length));h.Write((uint)words.Length);h.Write(body.ToArray());return packet.ToArray();}}}
 static byte[] Exact(Stream stream,int count){var b=new byte[count];int offset=0;while(offset<count){int n=stream.Read(b,offset,count-offset);if(n<=0)throw new IOException("O servidor encerrou a conexão RCON.");offset+=n;}return b;}
 public static string[] Decode(byte[] packet){if(packet.Length<12||BitConverter.ToUInt32(packet,4)!=packet.Length)throw new InvalidDataException("Tamanho RCON inválido.");uint count=BitConverter.ToUInt32(packet,8);if(count>4096)throw new InvalidDataException("Resposta RCON excessiva.");var words=new List<string>();int offset=12;for(uint i=0;i<count;i++){if(offset+4>packet.Length)throw new InvalidDataException("Resposta RCON incompleta.");uint len=BitConverter.ToUInt32(packet,offset);offset+=4;if(len>65536||offset+len>=packet.Length)throw new InvalidDataException("Palavra RCON incompleta.");words.Add(Encoding.UTF8.GetString(packet,offset,(int)len));offset+=(int)len;if(packet[offset++]!=0)throw new InvalidDataException("Terminador RCON inválido.");}if(offset!=packet.Length)throw new InvalidDataException("Resposta RCON com dados extras.");return words.ToArray();}
 public void Connect(string host,int port,string password){Dispose();try{client=new TcpClient();var ar=client.BeginConnect(host,port,null,null);if(!ar.AsyncWaitHandle.WaitOne(5000))throw new TimeoutException("O servidor não respondeu à conexão.");client.EndConnect(ar);client.NoDelay=true;stream=client.GetStream();stream.ReadTimeout=5000;stream.WriteTimeout=5000;var challenge=Command("login.hashed");if(challenge.Length<2)throw new InvalidDataException("O servidor não enviou o desafio de autenticação.");string salt=challenge[1];if(salt.Length!=32)throw new InvalidDataException("Desafio de autenticação inválido.");byte[] bytes=Enumerable.Range(0,16).Select(i=>Convert.ToByte(salt.Substring(i*2,2),16)).Concat(Encoding.UTF8.GetBytes(password)).ToArray();string hash;using(var md5=MD5.Create())hash=BitConverter.ToString(md5.ComputeHash(bytes)).Replace("-","");Command("login.hashed",hash);lastHost=host;lastPort=port;lastPassword=password;}catch{Dispose();throw;}}
 public void Reconnect(){if(lastHost==null)throw new InvalidOperationException("Conecte ao servidor primeiro.");Connect(lastHost,lastPort,lastPassword);}
 public string[] Command(params string[] words){lock(gate){if(stream==null)throw new InvalidOperationException("Conecte ao servidor primeiro.");uint id=sequence++&0x3fffffff;var bytes=Encode(id,words);stream.Write(bytes,0,bytes.Length);for(int tries=0;tries<32;tries++){var header=Exact(stream,12);uint size=BitConverter.ToUInt32(header,4);if(size<12||size>2*1024*1024)throw new InvalidDataException("Pacote RCON fora do limite.");var packet=header.Concat(Exact(stream,(int)size-12)).ToArray();uint received=BitConverter.ToUInt32(packet,0);if((received&0x3fffffff)!=id)continue;var reply=Decode(packet);if(reply.Length==0||reply[0]!="OK")throw new InvalidOperationException("Servidor: "+(reply.Length>0?reply[0]:"resposta vazia"));return reply;}throw new IOException("O servidor não respondeu ao comando solicitado.");}}
 public List<RotationEntry> Maps(){var list=new List<RotationEntry>();for(int offset=0;offset<1000;){var words=Command("mapList.list",offset.ToString());if(words.Length<3)throw new InvalidDataException("Lista de mapas inválida.");int count=Int32.Parse(words[1]),fields=Int32.Parse(words[2]);if(count<0||fields<3||fields>16||words.Length!=3+count*fields)throw new InvalidDataException("Formato da rotação inválido.");for(int i=0;i<count;i++)list.Add(new RotationEntry{Map=words[3+i*fields],Mode=words[4+i*fields],Rounds=Int32.Parse(words[5+i*fields])});if(count<100)return list;offset+=count;}throw new InvalidDataException("Rotação excede o limite de 1000 mapas.");}
 public static bool Same(List<RotationEntry> a,List<RotationEntry>b){return a.Select(x=>x.Signature).SequenceEqual(b.Select(x=>x.Signature));}
 void Replace(List<RotationEntry> entries){Command("mapList.clear");foreach(var e in entries)Command("mapList.add",e.Map,e.Mode,e.Rounds.ToString());if(!Same(entries,Maps()))throw new IOException("O servidor não confirmou a rotação solicitada.");Command("mapList.save");}
 public void SaveRotation(List<RotationEntry> baseline,List<RotationEntry> draft,string backup){if(draft.Count<1||draft.Count>1000||draft.Any(e=>e.Rounds<1||e.Rounds>99))throw new InvalidDataException("A rotação deve ter mapas e rodadas válidos.");var live=Maps();if(!Same(baseline,live))throw new IOException("A rotação mudou em outro painel. Atualize antes de salvar.");Directory.CreateDirectory(Path.GetDirectoryName(backup));File.WriteAllText(backup,new JavaScriptSerializer().Serialize(live),Encoding.UTF8);bool changed=false;try{Command("mapList.clear");changed=true;foreach(var e in draft)Command("mapList.add",e.Map,e.Mode,e.Rounds.ToString());if(!Same(draft,Maps()))throw new IOException("O servidor não confirmou os mapas.");Command("mapList.save");}catch(Exception ex){if(changed){try{Replace(live);}catch(Exception restore){throw new IOException("Falha ao salvar e ao restaurar a rotação. Backup: "+backup+". Erro de restauração: "+restore.Message);}}throw new IOException("Não foi possível salvar; a rotação anterior foi preservada/restaurada. "+ex.Message);}}
 public void Dispose(){if(stream!=null)stream.Dispose();if(client!=null)client.Close();stream=null;client=null;}
}
public static class Settings {
 public static Dictionary<string,string> Read(string root){var result=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);foreach(string line in File.ReadAllLines(Path.Combine(root,"config.txt"))){if(line.StartsWith("#"))continue;int pos=line.IndexOf('=');if(pos>0)result[line.Substring(0,pos).Trim()]=line.Substring(pos+1).Trim();}return result;}
 public static string Get(Dictionary<string,string>values,string key,string fallback){string v;return values.TryGetValue(key,out v)?v:fallback;}
 public static void Save(string root,Dictionary<string,string> values){string file=Path.Combine(root,"config.txt");byte[] original=File.ReadAllBytes(file);string text=Config.Decode(original);foreach(var kv in values){if(kv.Value.IndexOfAny(new[]{'\r','\n','\0'})>=0)throw new InvalidDataException("Valor inválido em "+kv.Key);string pattern=@"(?m)^"+System.Text.RegularExpressions.Regex.Escape(kv.Key)+@"=[^\r\n]*";if(System.Text.RegularExpressions.Regex.Matches(text,pattern).Count!=1)throw new InvalidDataException("Chave ausente ou duplicada: "+kv.Key);text=System.Text.RegularExpressions.Regex.Replace(text,pattern,m=>kv.Key+"="+kv.Value);}
 string folder=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"BF4BotLauncher","settings-backups");Directory.CreateDirectory(folder);File.WriteAllBytes(Path.Combine(folder,DateTime.Now.ToString("yyyyMMdd-HHmmssfff")+"-"+Guid.NewGuid().ToString("N")+".txt"),original);if(Config.Hash(File.ReadAllBytes(file))!=Config.Hash(original))throw new IOException("A configuração mudou enquanto você editava. Recarregue.");string tmp=file+"."+Guid.NewGuid().ToString("N")+".tmp";try{File.WriteAllText(tmp,text,new UTF8Encoding(false));File.Replace(tmp,file,null);}finally{if(File.Exists(tmp))File.Delete(tmp);}}
}
public sealed class MapOption {
 public string Id,Name;public string[] Modes;public override string ToString(){return Name;}
 public static string NameOf(string id){string n;return Names.TryGetValue(id,out n)?n:id;}
 public static readonly Dictionary<string,string> Names=new Dictionary<string,string>{{"MP_Abandoned","Zavod 311"},{"MP_Damage","Lancang Dam"},{"MP_Flooded","Flood Zone"},{"MP_Journey","Golmud Railway"},{"MP_Naval","Paracel Storm"},{"MP_Prison","Operation Locker"},{"MP_Resort","Hainan Resort"},{"MP_Siege","Siege of Shanghai"},{"MP_TheDish","Rogue Transmission"},{"MP_Tremors","Dawnbreaker"},{"MP_Playground","MP_Playground"},{"XP0_Caspian","Caspian Border 2014"},{"XP0_Firestorm","Operation Firestorm 2014"},{"XP0_Metro","Operation Metro 2014"},{"XP0_Oman","Gulf of Oman 2014"},{"XP1_001","Silk Road"},{"XP1_002","Altai Range"},{"XP1_003","Guilin Peaks"},{"XP1_004","Dragon Pass"},{"XP2_001","Lost Islands"},{"XP2_002","Nansha Strike"},{"XP2_003","Wave Breaker"},{"XP2_004","Operation Mortar"},{"XP3_MarketPl","Pearl Market"},{"XP3_UrbanGdn","Lumphini Garden"},{"XP3_Prpganda","Propaganda"},{"XP3_WtrFront","Sunken Dragon"},{"XP4_Arctic","Operation Whiteout"},{"XP4_SubBase","Hammerhead"},{"XP4_Titan","Hangar 21"},{"XP4_WlkrFtry","Giants of Karelia"},{"XP5_Night_01","Zavod: Graveyard Shift"},{"XP6_CMP","Operation Outbreak"},{"XP7_Valley","Dragon Valley 2015"}};
 public static List<MapOption> Load(string root){string json;var assembly=typeof(MapOption).Assembly;using(var s=assembly.GetManifestResourceStream("BF4Bots.Catalog")){if(s!=null)using(var r=new StreamReader(s))json=r.ReadToEnd();else json=File.ReadAllText(Path.Combine(root,"Server\\builtLevels.json"));}var doc=new JavaScriptSerializer().DeserializeObject(json) as Dictionary<string,object>;var list=new List<MapOption>();foreach(Dictionary<string,object> item in (object[])doc["Results"]){string level=(string)item["Level"],id=level.Split('/').Last();var modes=new List<string>();foreach(Dictionary<string,object> category in (object[])item["Categories"])if((string)category["Category"]=="GameMode")modes.AddRange(((object[])category["Mode"]).Select(x=>(string)x));list.Add(new MapOption{Id=id,Name=NameOf(id),Modes=modes.Distinct().ToArray()});}return list.OrderBy(x=>x.Id=="MP_Prison"?0:1).ThenBy(x=>x.Name).ToList();}
 public static string ModeName(string mode){switch(mode){case "ConquestLarge0":return "Conquista grande";case "ConquestSmall0":return "Conquista pequena";case "AirSuperiority0":return "Superioridade aérea";case "RushLarge0":return "Investida";case "TeamDeathMatch0":return "Mata-mata em equipe";case "Domination0":return "Dominação";case "GunMaster0":return "Mestre das armas";default:return mode;}}
}
}
